import{_ as d,o as e,c as r,ag as o}from"./chunks/framework.C9sp7nFj.js";const p=JSON.parse('{"title":"DCPOS","description":"","frontmatter":{},"headers":[],"relativePath":"2. 变量数据类型/2. 位置数据类型/DCPOS.md","filePath":"2. 变量数据类型/2. 位置数据类型/DCPOS.md","lastUpdated":1778862643000}'),a={name:"2. 变量数据类型/2. 位置数据类型/DCPOS.md"};function c(l,t,s,n,i,_){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="dcpos" tabindex="-1">DCPOS <a class="header-anchor" href="#dcpos" aria-label="Permalink to &quot;DCPOS&quot;">​</a></h1><p>笛卡尔相对位置类型</p><p>存储 TCP 点在笛卡尔坐标系下的相对偏移量。该变量可支持用户自主创建以及修改，也可在示教程序中进行赋值运算等操作。同时该变量支持在全局，工程，程序三大变量作用域中创建，删除，修改，复制，粘贴等操作（其中复制、粘贴操作不能跨域和跨工程）。</p><ul><li><strong>含义：</strong> 存储 TCP 点在笛卡尔坐标系下的<strong>相对位移偏移量</strong>。</li><li><strong>构成：</strong> <code>dx, dy, dz</code> (平移增量), <code>da, db, dc</code> (姿态旋转增量) 以及外部轴增量 <code>da7~da16</code>。</li><li><strong>场景：</strong> 典型的“偏移（Offset）”操作，比如在当前点沿 X 轴平移 50mm。</li></ul><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td><code>dx</code></td><td>real</td><td>TCP 点在参考坐标系上 x 方向的位移偏移量。</td><td>—</td></tr><tr><td><code>dy</code></td><td>real</td><td>TCP 点在参考坐标系上 y 方向的位移偏移量。</td><td>—</td></tr><tr><td><code>dz</code></td><td>real</td><td>TCP 点在参考坐标系上 z 方向的位移偏移量。</td><td>—</td></tr><tr><td><code>da</code></td><td>real</td><td>TCP 点相对参考坐标系 z 轴旋转的欧拉角偏移量。</td><td>—</td></tr><tr><td><code>db</code></td><td>real</td><td>TCP 点相对参考坐标系 y’轴旋转的欧拉角偏移量。</td><td>—</td></tr><tr><td><code>dc</code></td><td>real</td><td>TCP 点相对参考坐标系 x’’轴旋转的欧拉角偏移量。</td><td>—</td></tr><tr><td><code>da7</code></td><td>real</td><td>关节 7 号轴角度偏移量。</td><td>—</td></tr><tr><td><code>da16</code></td><td>real</td><td>关节 16 号轴角度偏移量。</td><td>机器人有几个轴就会显示几个轴的参数。</td></tr><tr><td><code>note</code></td><td>string</td><td>变量注释。</td><td>—</td></tr></tbody></table><ul><li>...：参数 da8~da15 的属性跟上述一样，都是 real 型变量，依次表示关节 8~关节 15 号轴角度偏移量。</li></ul>',6)])])}const h=d(a,[["render",c]]);export{p as __pageData,h as default};
